    start_group_recording: {
        parameters: {
            query?: never;
            header?: {
                /** @description Repeat this on a retry and the original writes are returned rather than a second recording started. Scoped to the group's first member, so one key answers for the whole submission. */
                "Idempotency-Key"?: string | null;
            };
            path: {
                /** @description Device group id, as written in the devices file. */
                id: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Recorded, one write per member. The three lifecycle verbs are expanded under a rendezvous, so `batch` is set and no member is dispatched until every one is ready. */
            202: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Acceptance"];
                };
            };
            /** @description No device group has this id. A device id here is this same 404, with the `/v1/writes/devices` URL that would have worked. */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ApiError"];
                };
            };
            /** @description One member refused, so the whole submission was refused and nothing was recorded — admission is across every member at once. The body names the member and its desired recording state. */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ApiError"];
                };
            };
            /** @description The storage backend failed. */
            500: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ApiError"];
                };
            };
        };
    };
